def _render(svg: str, color: str, size: int, ratio: float) -> QPixmap:
    renderer = QSvgRenderer(QByteArray(svg.replace('fill="currentColor"', f'fill="{color}"').encode("utf-8")))
    px = max(1, round(size * ratio))
    pixmap = QPixmap(px, px)
    pixmap.fill(Qt.transparent)
    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.Antialiasing)
    renderer.render(painter)
    painter.end()
    pixmap.setDevicePixelRatio(ratio)
    return pixmap


def get_svg_icon(name: str, color: str = "#e9ebef", size: int = 18) -> QIcon:
    svg = ICONS_SVG.get(name) or ICONS_SVG["cube"]
    screen = QGuiApplication.primaryScreen() if QGuiApplication.instance() else None
    ratio = screen.devicePixelRatio() if screen else 1.0
    icon = QIcon()
    icon.addPixmap(_render(svg, color, size, ratio), QIcon.Mode.Normal)
    icon.addPixmap(_render(svg, "#4c5262", size, ratio), QIcon.Mode.Disabled)
    return icon
